[ExtensionOf(classStr(VendInvoicePaymentAuthorizationTask))]
final class METVendInvoicePaymentAuthorizationTask_Extension
{
}

Method.Source:
    /// <summary>
    /// MPJ_2677 - Kscerri - 10/06/2021
    /// After Vendor invoice is posted creats the freetext invoice and posts
    /// </summary>
    /// <param name = "_workflowElementEventArgs">worfklow element event </param>
    public void execute(WorkflowElementEventArgs _workflowElementEventArgs)
    {
        PurchParameters         purchParameters;
        PurchTable              purchTable;
        ReasonTableRef          reasonTableRef;
        VendInvoiceInfoTable    vendInvoiceInfoTable;
        CustInvoiceTable        custInvoiceTable;
        CustInvoiceLine         custInvoiceLine;
        CustPostInvoice         custPostInvoice;
        PurchLine               purchLine;
        RecordInsertList        custInvoiceLineList;

        next execute(_workflowElementEventArgs);

        vendInvoiceInfoTable = VendInvoiceInfoTable::findRecId(_workflowElementEventArgs.parmWorkflowContext().parmRecId());

        //if (this.isInvoiceReadyForPosting(vendInvoiceInfoTable) && vendInvoiceInfoTable.RequestStatus == VendInvoiceRequestStatus::Approved)
        if (vendInvoiceInfoTable.Num)
        {
            purchParameters  = PurchParameters::find();
            purchTable       = purchTable::find(vendInvoiceInfoTable.PurchId);
            reasonTableRef   = ReasonTableRef::find(purchTable.ReasonTableRef);

            if (reasonTableRef.Reason == purchParameters.METPOReason)
            {
                try
                {
                    ttsBegin;
                    // Create header
                    custInvoiceTable.clear();
                    custInvoiceTable.initValue();
                    custInvoiceTable.OrderAccount = purchTable.METCustAcc;
                    custInvoiceTable.modifiedField(fieldNum(CustInvoiceTable, OrderAccount));
                    CustInvoiceTable.CustomerRef = vendInvoiceInfoTable.Num;
                    custInvoiceTable.insert();
                    
                    custInvoiceLineList = new RecordInsertList(tableNum(CustInvoiceLine));

                    // Create line
                    while select purchLine
                        where purchLine.PurchId == vendInvoiceInfoTable.PurchId
                    {
                        custInvoiceLine.clear();
                        custInvoiceLine.initValue();
                        custInvoiceLine.ParentRecId         = custInvoiceTable.RecId;
                        custInvoiceLine.initFromCustInvoiceTable(custInvoiceTable);
                        custInvoiceLine.Description         = purchLine.name;
                        custInvoiceLine.LedgerDimension     = purchParameters.METLedgerDimension;
                        custInvoiceLine.TaxGroup            = CustTable::find(purchTable.METCustAcc).TaxGroup;
                        custInvoiceLine.Quantity            = purchLine.PurchQty;
                        custInvoiceLine.modifiedField(fieldNum(CustInvoiceLine, Quantity));
                        custInvoiceLine.UnitPrice           = purchLine.PurchPrice;
                        custInvoiceLine.modifiedField(fieldNum(CustInvoiceLine, UnitPrice));
                        custInvoiceLine.DefaultDimension    = purchLine.DefaultDimension;

                        custInvoiceLine.modifiedField(fieldNum(CustInvoiceLine, LedgerDimension));
                        //custInvoiceLine.insert();
                        custInvoiceLineList.add(custInvoiceLine);
                    }
                    //Insert CustInvoiceLines in DB;
                    custInvoiceLineList.insertDatabase();

                    // Post
                    custPostInvoice = new CustPostInvoice(custInvoiceTable);
                    custPostInvoice.run();
        
                    ttscommit;
                }
                catch
                {
                    throw error(error::wrongUseOfFunction(funcName()));
                }
            }
        }
    }

